INSERT INTO public.paper (id, project_id, user_id, title, authors, year, doi, pdf_url, summary, status, created_time, folder_id) VALUES (8, 2, 2, 'Blumstein.pdf', NULL, NULL, NULL, 'papers/5a4d027f-1a5f-4654-9138-f18fca533d27/Blumstein.pdf', '{"doi": "10.1111/j.1365-2664.2011.01993.x", "tags": [{"name": "Acoustic Monitoring", "category": "Engineering"}, {"name": "Signal Processing", "category": "Engineering"}, {"name": "Bioacoustics", "category": "Biology"}, {"name": "Ecology", "category": "Biology"}, {"name": "Conservation Biology", "category": "Biology"}, {"name": "Sensor Networks", "category": "Engineering"}], "year": 2011, "title": "Acoustic monitoring in terrestrial environments using microphone arrays: applications, technological considerations and prospectus", "method": "This paper is a comprehensive narrative review of terrestrial bioacoustic monitoring using microphone arrays, synthesizing existing technologies, algorithmic advances, and applications across ecological, behavioural, and conservation research. The authors draw on case studies from multiple taxa (including birds, elephants, anurans, and insects) to illustrate the capabilities of array systems for non-invasive animal monitoring. The review is framed to bridge communication between field ecologists and bioacoustics engineers, outlining key concepts and shared research needs.", "authors": "Daniel T. Blumstein, Daniel J. Mennill, Patrick Clemins, Lewis Girod, Kung Yao, Gail Patricelli, Jill L. Deppe, Alan H. Krakauer, Christopher Clark, Kathryn A. Cortopassi, Sean F. Hanser, Brenda McCowan, Andreas M. Ali, Alexander N. G. Kirschel", "finding": "The review finds that microphone array systems paired with advancing signal recognition algorithms enable non-invasive, remote monitoring across scales, from fine-scale signal directionality studies to large-scale population and biodiversity surveys. Acoustic approaches can outperform traditional human field surveys for certain taxa (e.g., bird communities) and are particularly valuable for detecting rare or endangered species in inaccessible habitats. These technologies also support research on soundscapes, anthropogenic noise impacts, species interactions, social dynamics, and the effects of climate change and habitat fragmentation on phenology and biodiversity.", "limitation": "A primary identified limitation of terrestrial acoustic monitoring with microphone arrays is the difficulty of performing robust signal recognition across a wide range of taxa, with many existing tools restricted to specific species or groups. There is currently no shared, standardized framework for signal recognition, meaning data from different species or systems cannot be easily analysed across disparate platforms. These challenges limit the scalability and broad applicability of acoustic monitoring across diverse ecological contexts.", "future_work": "The authors recommend that the bioacoustics community prioritize developing a unified, standardized framework for signal recognition to enable interoperability across analysis systems and support cross-taxa acoustic data analysis. They also suggest expanding the use of microphone array technology to support wildlife management and long-term conservation monitoring, including tracking the impacts of climate change, habitat fragmentation, and anthropogenic noise on biodiversity and phenology. Further, they advocate for increased collaboration between field ecologists and bioacoustics engineers to align technological development with real-world ecological research and management needs."}', 'READY', '2026-08-07 09:32:01.950579+08', 3);
