INSERT INTO public.paper (id, project_id, user_id, title, authors, year, doi, pdf_url, summary, status, created_time, folder_id) VALUES (2, 2, 2, 'test_paper.pdf', NULL, NULL, NULL, 'D:\\AI-research-OS\\ai-service\\tests\\test_paper.pdf', '{"doi": "", "tags": [{"name": "Artificial Intelligence", "category": "Artificial Intelligence"}, {"name": "Deep Learning", "category": "Artificial Intelligence"}, {"name": "Computer Vision", "category": "Artificial Intelligence"}, {"name": "Transformer Architecture", "category": "Artificial Intelligence"}, {"name": "Neural Networks", "category": "Artificial Intelligence"}], "year": null, "title": "An Image is Worth 16x16 Words", "method": "The paper proposes a Vision Transformer (ViT) architecture for image classification. The approach splits input images into patches, which are processed using a standard transformer-based pipeline.", "authors": "Dosovitskiy et al.", "finding": "The proposed ViT model achieves 95% accuracy on the ImageNet dataset. It outperforms previous CNN-based image classification methods by a 3% accuracy margin.", "limitation": "", "future_work": "The authors suggest exploring multi-scale architectures as future work. The full set of future research directions is not specified in the provided truncated text."}', 'READY', '2026-07-11 00:56:07.170107+08', 3);
INSERT INTO public.paper (id, project_id, user_id, title, authors, year, doi, pdf_url, summary, status, created_time, folder_id) VALUES (9, 2, 2, 'Bouchet.pdf', NULL, NULL, NULL, 'papers/229bbcde-6e26-4a38-9e49-cf4f70bdd710/Bouchet.pdf', '{"doi": "", "tags": [{"name": "Bioacoustics", "category": "Biology"}, {"name": "Animal Behavior", "category": "Biology"}, {"name": "Acoustic Signal Processing", "category": "Engineering"}, {"name": "Statistical Analysis", "category": "Mathematics"}, {"name": "Primatology", "category": "Biology"}, {"name": "Comparative Psychology", "category": "Psychology"}], "year": 2012, "title": "Acoustic Variability and Individual Distinctiveness in the Vocal Repertoire of Red-Capped Mangabeys (Cercocebus torquatus)", "method": "This study recorded the six most common call types from 14 adult captive red-capped mangabeys to assess intra- and interindividual acoustic variability using a range of temporal and frequency parameters. The researchers compared acoustic variability and individual distinctiveness across call types to test predictions from three existing hypotheses about the evolution of acoustic variability in animal vocal signals.", "authors": "Hélène Bouchet, Catherine Blois-Heulin, Anne-Sophie Pellier, Klaus Zuberbühler, Alban Lemasson", "finding": "Acoustic variability was highest in contact and threat calls, intermediate in food calls, and lowest in loud and alarm calls. Individual distinctiveness was high in contact, threat, loud, and alarm calls, and low in food calls. Calls mediating intragroup social interactions were structurally most variable and individually most distinctive, highlighting the key role of social factors in the evolution of this species'' vocal repertoire.", "limitation": "", "future_work": ""}', 'READY', '2026-08-07 09:32:02.067191+08', 3);
INSERT INTO public.paper (id, project_id, user_id, title, authors, year, doi, pdf_url, summary, status, created_time, folder_id) VALUES (4, 4, 6, 'test-paper.pdf', NULL, NULL, NULL, 'papers/7773083d-2010-45b9-9285-e3b40c7780eb/test-paper.pdf', NULL, 'FAILED', '2026-08-06 12:33:12.823352+08', NULL);
