INSERT INTO public.paper (id, project_id, user_id, title, authors, year, doi, pdf_url, summary, status, created_time, folder_id) VALUES (12, 2, 2, 'Clink-2.pdf', NULL, NULL, NULL, 'papers/027cab99-f673-4c0c-baa1-ad4ca931bb90/Clink-2.pdf', '{"doi": "10.1111/2041-210X.13520", "tags": [{"name": "Unsupervised Learning", "category": "Artificial Intelligence"}, {"name": "Acoustic Signal Processing", "category": "Engineering"}, {"name": "Cluster Validation", "category": "Artificial Intelligence"}, {"name": "Bioacoustics", "category": "Biology"}, {"name": "Wildlife Monitoring", "category": "Biology"}, {"name": "Conservation Biology", "category": "Biology"}], "year": 2021, "title": "Unsupervised acoustic classification of individual gibbon females and the implications for passive acoustic monitoring", "method": "The study tested three unsupervised clustering algorithms (affinity propagation, K-medoids, and Gaussian mixture model-based clustering) on a dataset of known-identity Northern gray gibbon female great calls collected from five sites in Malaysian Borneo, to evaluate their ability to distinguish individual callers for passive acoustic monitoring applications. Internal validation of cluster solutions was conducted using silhouette coefficients, while external validation compared clustering results to known female identity labels via normalized mutual information and classification accuracy, calculated by assigning each cluster to the female with the highest number of calls in that cluster. The authors assessed algorithm performance across varying numbers of females (10 to 50) and cross-site bootstrap samples to evaluate robustness and ecological relevance.", "authors": "Dena J. Clink, Holger Klinck", "finding": "Affinity propagation clustering consistently outperformed both K-medoids and Gaussian mixture model-based clustering across all evaluation metrics used. The classification accuracy of affinity propagation was more stable as the number of females increased and when females were randomly sampled across different study sites. Unsupervised clustering techniques show promise for providing individual identity information to support passive acoustic monitoring of vocally distinct animal species.", "limitation": "", "future_work": ""}', 'READY', '2026-08-07 09:32:02.357477+08', NULL);
INSERT INTO public.paper (id, project_id, user_id, title, authors, year, doi, pdf_url, summary, status, created_time, folder_id) VALUES (10, 2, 2, 'Chen.pdf', NULL, NULL, NULL, 'papers/5311b744-74e4-455f-a769-71955f8503a4/Chen.pdf', '{"doi": "", "tags": [{"name": "Deep Learning", "category": "Artificial Intelligence"}, {"name": "Convolutional Neural Networks", "category": "Artificial Intelligence"}, {"name": "Feature Fusion", "category": "Artificial Intelligence"}, {"name": "Model Compression", "category": "Artificial Intelligence"}, {"name": "Signal Processing", "category": "Engineering"}, {"name": "Acoustics", "category": "Engineering"}], "year": 2024, "title": "ERes2NetV2: Boosting Short-Duration Speaker Verification Performance with Computational Efficiency", "method": "This paper proposes ERes2NetV2, an enhanced ERes2Net architecture designed to improve short-duration speaker verification performance while maintaining computational efficiency. It integrates two core modules: Bottom-up Dual-stage Feature Fusion (BDFF), which fuses multi-scale features from stages 3 and 4 via attentional feature fusion to reduce structural redundancy in global feature interaction, and Bottleneck-like Local Feature Fusion (BLFF), which uses an expand-reduce-expand channel structure within residual blocks to strengthen short-duration feature extraction while reducing parameter count and computational complexity.", "authors": "Yafeng Chen, Siqi Zheng, Hui Wang, Luyao Cheng, Qian Chen, Shiliang Zhang, Junjie Li", "finding": "Experiments on VoxCeleb and 3D-Speaker datasets show that ERes2NetV2 outperforms the baseline ERes2Net across full and short-duration trials, achieving 0.61% EER on full-duration VoxCeleb1-O, 0.98% for 3-second trials, and 1.48% for 2-second trials. Compared to a channel-expanded ERes2Net variant without BDFF and BLFF, ERes2NetV2 reduces parameter count and FLOPs significantly while retaining competitive verification performance, demonstrating its efficiency.", "limitation": "", "future_work": ""}', 'READY', '2026-08-07 09:32:02.192113+08', NULL);
INSERT INTO public.paper (id, project_id, user_id, title, authors, year, doi, pdf_url, summary, status, created_time, folder_id) VALUES (11, 2, 2, 'Clemins.pdf', NULL, NULL, NULL, 'papers/9f334a77-30a8-4405-bd23-46f40158c85c/Clemins.pdf', '{"doi": "", "tags": [{"name": "Speech Recognition", "category": "Artificial Intelligence"}, {"name": "Signal Processing", "category": "Engineering"}, {"name": "Machine Learning", "category": "Artificial Intelligence"}, {"name": "Bioacoustics", "category": "Biology"}, {"name": "Acoustics", "category": "Engineering"}, {"name": "Animal Communication", "category": "Biology"}], "year": 2003, "title": "Application of Speech Recognition to African Elephant (Loxodonta africana) Vocalizations", "method": "This work applies speech recognition methodologies to African elephant vocalizations, using Hidden Markov Models (HMMs) implemented via the HTK 3.1.1 toolkit for both call classification and speaker identification tasks. Features consist of 12 mel-frequency cepstral coefficients plus log energy, with adjusted mel filter banks emphasizing the infrasound frequency range used by elephants, and modified frame sizes tailored to each task to account for elephants'' low fundamental vocal frequencies. Data was collected from captive African elephants using collar-mounted microphones, with time-synchronized video used to label vocalizations.", "authors": "Patrick J. Clemins, Michael T. Johnson", "finding": "The study achieved initial classification accuracies of 83.8% for vocalization call classification and 88.1% for speaker identification on captive African elephant vocalization data. These results demonstrate that speech processing algorithms can be successfully adapted for automatic animal vocalization analysis, offering benefits over manual spectrogram-based classification such as reduced human bias and faster processing.", "limitation": "The dataset is limited to a small group of captive African elephants, so results may not generalize to wild populations or larger, more diverse groups. Recordings include environmental noise that can degrade classification performance, particularly when noise characteristics vary across the dataset. Additionally, label validity is constrained as researchers can only infer the categorical and communicative meaning of vocalizations rather than confirming them directly.", "future_work": "The long-term goal of this research is to develop a universal analysis framework and robust feature set for animal vocalizations that can be applied across many different species. Future work will likely address key challenges including integrating noise models to improve classification robustness in variable recording environments, and expanding datasets to enhance the generalizability of results."}', 'READY', '2026-08-07 09:32:02.278614+08', NULL);
INSERT INTO public.paper (id, project_id, user_id, title, authors, year, doi, pdf_url, summary, status, created_time, folder_id) VALUES (6, 2, 2, 'Bermant.pdf', NULL, NULL, NULL, 'papers/8359a2eb-ee3a-45ff-a8b5-25b8138aae53/Bermant.pdf', '{"doi": "10.1038/s41598-019-48909-4", "tags": [{"name": "Deep Learning", "category": "Artificial Intelligence"}, {"name": "Signal Processing", "category": "Engineering"}, {"name": "Computer Vision", "category": "Artificial Intelligence"}, {"name": "Sequence Modeling", "category": "Artificial Intelligence"}, {"name": "Bioacoustics", "category": "Biology"}, {"name": "Marine Biology", "category": "Biology"}], "year": 2019, "title": "Deep Machine Learning Techniques for the Detection and Classification of Sperm Whale Bioacoustics", "method": "The study employed Convolutional Neural Networks (CNNs) to build an echolocation click detector that classifies spectrograms from sperm whale acoustic data for the presence or absence of a click. It also trained long short-term memory (LSTM) and gated recurrent unit (GRU) recurrent neural networks for three supervised classification tasks: coda type classification, vocal clan classification, and individual whale identification, using labeled datasets from Dominica and the Eastern Tropical Pacific.", "authors": "Peter C. Bermant, Michael M. Bronstein, Robert J. Wood, Shane Gero, David F. Gruber", "finding": "The CNN click detector achieved 99.5% accuracy on 650 spectrograms. RNN-based classification reached 97.5% accuracy for 23 Dominica coda types (8,719 codas) and 93.6% for 43 Eastern Tropical Pacific coda types (16,995 codas), 95.3% accuracy for two Dominica vocal clans and 93.1% for four Eastern Tropical Pacific clans, and 99.4% accuracy for individual identification of two Dominica sperm whales. These results confirm the feasibility of applying deep learning to sperm whale bioacoustics and validate that neural networks can learn meaningful representations of whale vocalizations.", "limitation": "The individual whale identification task was tested on only two Dominica sperm whales, representing a small sample that may restrict generalizability to larger populations or other geographic regions. The study primarily focuses on echolocation clicks and codas, so performance on less common sperm whale call types such as buzzes and slow clicks has not been evaluated.", "future_work": "Future studies could train CNN-based architectures to extract finer-scale details from cetacean spectrograms, building on the successful echolocation click detector results. Additional research could expand deep learning classification to additional sperm whale call types and larger, more diverse acoustic datasets to help address the bottleneck of manual annotation in cetacean bioacoustic research."}', 'READY', '2026-08-07 09:31:48.433795+08', 3);
INSERT INTO public.paper (id, project_id, user_id, title, authors, year, doi, pdf_url, summary, status, created_time, folder_id) VALUES (13, 2, 2, 'Clink.pdf', NULL, NULL, NULL, 'papers/e4a16061-60e4-4f23-a03a-2bb8ac03e288/Clink.pdf', '{"doi": "10.1080/09524622.2018.1426042", "tags": [{"name": "Machine Learning", "category": "Artificial Intelligence"}, {"name": "Signal Processing", "category": "Engineering"}, {"name": "Bioacoustics", "category": "Biology"}, {"name": "Passive Acoustic Monitoring", "category": "Biology"}, {"name": "Wildlife Conservation", "category": "Biology"}, {"name": "Animal Behavior", "category": "Biology"}], "year": 2019, "title": "Application of a semi-automated vocal fingerprinting approach to monitor Bornean gibbon females in an experimentally fragmented landscape in Sabah, Malaysia", "method": "This study uses a semi-automated vocal fingerprinting approach for individual female gibbon identification, consisting of manual call extraction from field recordings followed by automated feature extraction using Mel-frequency cepstral coefficients (MFCCs), tested with two feature aggregation strategies: time-window averaging and standardized time-window counts. Classification of individual identity is performed using both linear discriminant analysis and multi-class support vector machines (SVMs) with multiple kernel types, with model performance evaluated via random training-test splits and leave-one-out cross-validation.", "authors": "Dena J. Clink, Margaret C. Crofoot, Andrew J. Marshall", "finding": "MFCC-based feature extraction outperformed traditional spectrogram features for female gibbon identification, with LDA accuracy reaching 98.4% for averaged MFCCs and 98.9% for standardized time-window MFCCs, compared to 95.7% accuracy with spectrogram features. SVM classification achieved even higher performance, with 98.8% accuracy on held-out test data across 100 iterations and 99.5% accuracy on the full dataset via leave-one-out cross-validation. Cross-season classification of four females recorded across multiple seasons had limited success, indicating potential temporal variability in vocal features that challenges long-term individual identification.", "abstract": "Passive acoustic monitoring using vocal fingerprinting is a promising non-invasive tool for wildlife conservation, but traditional manual spectrogram-based feature extraction methods are labor-intensive and subjective. This study develops and tests a semi-automated vocal fingerprinting approach using Mel-frequency cepstral coefficients (MFCCs) to identify female Bornean gibbons, comparing two MFCC feature aggregation methods and evaluating classification performance via linear discriminant analysis (LDA) and support vector machines (SVMs). The approach achieved up to 99.5% female identification accuracy with SVM (validated via leave-one-out cross-validation), outperforming spectrogram-based LDA, though cross-season classification for four females with multi-season recordings had limited success.", "keywords": ["Support vector machine", "Mel-frequency cepstral coefficients", "Hylobates", "Stability of Altered Forest Ecosystems Project", "vocal fingerprinting", "acoustic monitoring"], "workflow": "First, recordings of female Bornean gibbon great calls were collected at the Stability of Altered Forest Ecosystems (SAFE) site in Sabah, Malaysia across multiple field seasons between 2013 and 2016, using directional microphones and digital recorders, with occasional playback of duets to elicit vocal responses, and individual females were identified based on recording location, group composition, and unique behavioral traits. Next, manual pre-processing was performed to isolate and extract 376 individual calls from 33 females from the raw recordings. Two MFCC feature extraction methods were then applied to each call: averaging MFCC values across all time windows, and generating a standardized number of time windows per call. Initial classification accuracy was compared between MFCC-derived features and traditional spectrogram features using linear discriminant analysis (LDA). Multi-class SVM models with four different kernel types were subsequently tested over 100 iterations of random training-test splits to assess prediction accuracy and select the optimal kernel. The best-performing SVM model was validated on the full dataset using leave-one-out cross-validation, and its performance was compared to LDA results. Finally, the SVM method was applied to a reduced dataset of four females with recordings from at least three separate seasons to evaluate cross-season individual identification performance.", "limitation": "The method is semi-automated, requiring manual pre-processing to identify and extract calls from raw recordings, which is labor-intensive and limits scalability for large-scale passive acoustic monitoring datasets. The limited success of cross-season classification suggests that gibbon vocal features may change over time, reducing the reliability of vocal fingerprinting for long-term individual monitoring without periodic model retraining. Additionally, the dataset is restricted to 33 female gibbons at a single study site, so the generalizability of the approach to other gibbon populations, species, or habitat types remains untested.", "future_work": "Future research should develop fully automated call detection and extraction pipelines to eliminate the manual pre-processing step, enabling scalable application to large passive acoustic monitoring datasets. Additional work is needed to characterize temporal variation in gibbon vocal features and develop adaptive classification methods that account for such variation to improve long-term cross-season individual identification. The proposed approach should also be tested on additional gibbon species and geographically distinct populations to assess its generalizability for broader wildlife conservation monitoring applications."}', 'READY', '2026-08-07 09:32:02.446386+08', NULL);


